import sales from './sales.json' with {type:'json'};

const ISO_DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

function isValidIsoDate(s) {
  if (typeof s !== 'string' || !ISO_DATE_RE.test(s)) return false;
  const d = new Date(s + 'T00:00:00Z');
  if (isNaN(d.getTime())) return false;
  // check round-trip to ensure real calendar date
  return d.toISOString().slice(0, 10) === s;
}

export async function listTools() {
  return [
    {
      name: 'sales_report',
      description: 'Sum sales rows in an inclusive date range and return the total amount and row count.',
      inputSchema: {
        type: 'object',
        properties: {
          start_date: { type: 'string', description: 'Inclusive range start as an ISO date (YYYY-MM-DD).' },
          end_date: { type: 'string', description: 'Inclusive range end as an ISO date (YYYY-MM-DD).' },
        },
        required: ['start_date', 'end_date'],
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'sales_report') {
    throw new Error(`Unknown tool: ${name}`);
  }
  const allowed = new Set(['start_date', 'end_date']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error(`Unknown field: ${key}`);
    }
  }
  const { start_date, end_date } = args;
  if (typeof start_date !== 'string' || typeof end_date !== 'string') {
    throw new Error('start_date and end_date are required');
  }
  if (!isValidIsoDate(start_date)) {
    throw new Error(`Invalid start_date: ${start_date}`);
  }
  if (!isValidIsoDate(end_date)) {
    throw new Error(`Invalid end_date: ${end_date}`);
  }
  if (start_date > end_date) {
    throw new Error('start_date must not be after end_date');
  }
  let total = 0;
  let count = 0;
  for (const row of sales) {
    if (row.date >= start_date && row.date <= end_date) {
      total += row.amount;
      count += 1;
    }
  }
  return {
    content: [
      { type: 'text', text: `Total: ${total}, Rows: ${count}` },
    ],
  };
}
